// ABSTRACTION: contract — tells callers what a Shape can do, not how
abstract class Shape {
    private String color;                  // ENCAPSULATION: private field

    Shape(String color) { this.color = color; }

    public String getColor() { return color; }    // controlled access

    public abstract double area();         // subclasses must implement 'how'

    // Overloading — compile-time polymorphism (same name, different params)
    public void describe() {
        System.out.println(color + " shape");
    }
    public void describe(boolean verbose) {
        System.out.println(color + " shape, area=" + area());
    }
}

// INHERITANCE: Circle IS-A Shape
class Circle extends Shape {
    private final double radius;

    Circle(String color, double radius) {
        super(color);
        this.radius = radius;
    }

    @Override
    public double area() {               // POLYMORPHISM: runtime override
        return Math.PI * radius * radius;
    }
}

class Rectangle extends Shape {
    private final double width, height;

    Rectangle(String color, double width, double height) {
        super(color);
        this.width = width;
        this.height = height;
    }

    @Override
    public double area() { return width * height; }
}

public class OopDemo {
    public static void main(String[] args) {
        Shape s1 = new Circle("red", 5);        // parent reference, child object
        Shape s2 = new Rectangle("blue", 4, 6);

        // Runtime dispatch — JVM picks Circle.area() or Rectangle.area()
        System.out.println(s1.area());  // 78.54
        System.out.println(s2.area());  // 24.0

        s1.describe();          // overloaded method — no verbose output
        s1.describe(true);      // compile-time dispatch picks describe(boolean)
    }
}
